package br.com.onda;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.media3.common.*;
import androidx.media3.session.*;
import androidx.media3.session.MediaController;
import com.google.common.util.concurrent.ListenableFuture;
import java.io.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import org.junit.*;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class DjDurationFlowTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private Activity anchor;private DjActivity screen;private MediaController player;private ListenableFuture<MediaController> connection;private File file;private String oldLists;private int oldMode,oldSize;
 private interface Check{boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{for(int n=0;n<300;n++){boolean[] done={false};ins.runOnMainSync(()->{try{done[0]=check.ready();}catch(Exception e){throw new RuntimeException(e);}});if(done[0])return;Thread.sleep(50);}fail("DJ duration scenario timed out");}
 private Object field(String name)throws Exception{java.lang.reflect.Field f=DjActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(screen);}
 private List<MediaItem> queue()throws Exception{return new ArrayList<>((List<MediaItem>)field("queue"));}
 private MediaItem song(String id,long duration){Bundle b=new Bundle();b.putLong("durationMs",duration);return new MediaItem.Builder().setMediaId(id).setUri(Uri.fromFile(file)).setMediaMetadata(new MediaMetadata.Builder().setTitle("Música "+id).setArtist("Artista "+id).setExtras(b).build()).build();}
 private void invoke(String name)throws Exception{java.lang.reflect.Method method=DjActivity.class.getDeclaredMethod(name);method.setAccessible(true);method.invoke(screen);}
 @Before public void before()throws Exception{oldLists=c.getSharedPreferences("playlists",0).getString("lists","[]");oldMode=c.getSharedPreferences("dj",0).getInt("mode",0);oldSize=c.getSharedPreferences("dj",0).getInt("size",1);c.getSharedPreferences("playlists",0).edit().putString("lists","[]").commit();c.getSharedPreferences("dj",0).edit().putInt("mode",0).putInt("size",1).commit();file=AudioTestFixtures.tone(c,30000);anchor=ins.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->anchor.hasWindowFocus());ins.runOnMainSync(()->connection=new MediaController.Builder(c,new SessionToken(c,new ComponentName(c,PlaybackService.class))).buildAsync());player=connection.get(15,TimeUnit.SECONDS);ins.runOnMainSync(()->{player.pause();player.setMediaItem(song("999",30000),5000);player.prepare();});waitFor(()->player.getPlaybackState()==Player.STATE_READY);screen=(DjActivity)ins.startActivitySync(new Intent(c,DjActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->(boolean)field("loaded")&&screen.hasWindowFocus());ins.runOnMainSync(()->{try{List<MediaItem> library=(List<MediaItem>)field("library");library.clear();library.addAll(Arrays.asList(song("101",600000),song("102",480000),song("103",420000),song("104",1200000),song("download:105",0)));invoke("mix");}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->((Button)field("refresh")).isEnabled()&&!queue().isEmpty());}
 @After public void after(){ins.runOnMainSync(()->{if(screen!=null)screen.finish();if(player!=null){player.pause();player.stop();player.clearMediaItems();}if(anchor!=null)anchor.finish();if(connection!=null)MediaController.releaseFuture(connection);});ins.waitForIdleSync();c.getSharedPreferences("playlists",0).edit().putString("lists",oldLists).commit();c.getSharedPreferences("dj",0).edit().putInt("mode",oldMode).putInt("size",oldSize).commit();if(file!=null)file.delete();}
 @Test public void durationPreviewFitsWholeSongsAndPreservesCurrentTrack()throws Exception{ins.runOnMainSync(()->{try{((Spinner)field("size")).setSelection(3);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->{if(!((Button)field("refresh")).isEnabled()||queue().isEmpty())return false;long sum=0;for(MediaItem item:queue()){long d=LibraryStore.number(item,"durationMs");if(d<=0)return false;sum+=d;}return sum<=900000;});ins.runOnMainSync(()->{assertEquals("999",player.getCurrentMediaItem().mediaId);assertEquals(5000,player.getCurrentPosition(),100);assertFalse(player.getPlayWhenReady());try{assertTrue(((TextView)field("status")).getText().toString().contains("em 1×"));}catch(Exception e){throw new RuntimeException(e);}});capture();}
 private EditText input(View view){if(view instanceof EditText)return (EditText)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){EditText found=input(((ViewGroup)view).getChildAt(i));if(found!=null)return found;}return null;}
 @Test public void confirmedSaveUsesSnapshotOrderAndDoesNotChangePlayback()throws Exception{List<String> expected=new ArrayList<>();ins.runOnMainSync(()->{try{for(MediaItem item:queue())expected.add(item.mediaId);invoke("saveSelection");}catch(Exception e){throw new RuntimeException(e);}});ins.waitForIdleSync();ins.runOnMainSync(()->{try{AlertDialog dialog=(AlertDialog)field("saveDialog");assertTrue(dialog.isShowing());EditText name=input(dialog.getWindow().getDecorView());assertNotNull(name);name.setText("Viagem de teste");Collections.reverse((List<MediaItem>)field("queue"));dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertFalse(dialog.isShowing());assertEquals("999",player.getCurrentMediaItem().mediaId);assertFalse(player.getPlayWhenReady());}catch(Exception e){throw new RuntimeException(e);}});List<PlaylistStore.Entry> saved=PlaylistStore.read(c);assertEquals(1,saved.size());assertEquals("Viagem de teste",saved.get(0).name);assertEquals(expected,saved.get(0).songs);assertEquals(expected,PlaylistStore.decode(c.getSharedPreferences("playlists",0).getString("lists","[]")).get(0).songs);}
 @Test public void invalidNamesIdsAndDuplicatesNeverOverwriteExistingPlaylists()throws Exception{PlaylistStore.create(c,"Coração",Arrays.asList("101","download:105","101"));String before=c.getSharedPreferences("playlists",0).getString("lists","");for(String name:Arrays.asList("","Coracao")){try{PlaylistStore.create(c,name,Arrays.asList("102"));fail("Invalid or duplicate name must be rejected");}catch(IllegalArgumentException expected){}assertEquals(before,c.getSharedPreferences("playlists",0).getString("lists",""));}try{PlaylistStore.create(c,"Inválida",Arrays.asList("https://example.org"));fail();}catch(IllegalArgumentException expected){}assertEquals(before,c.getSharedPreferences("playlists",0).getString("lists",""));assertEquals(Arrays.asList("101","download:105"),PlaylistStore.read(c).get(0).songs);}
 @Test public void countModeStillIncludesUnknownDurationAndCancelSavesNothing()throws Exception{ins.runOnMainSync(()->{try{assertEquals(7,((Spinner)field("size")).getAdapter().getCount());assertTrue(queue().stream().anyMatch(i->i.mediaId.equals("download:105")));invoke("saveSelection");}catch(Exception e){throw new RuntimeException(e);}});ins.waitForIdleSync();ins.runOnMainSync(()->{try{AlertDialog dialog=(AlertDialog)field("saveDialog");dialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();assertEquals("999",player.getCurrentMediaItem().mediaId);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->!((AlertDialog)field("saveDialog")).isShowing());assertTrue(PlaylistStore.read(c).isEmpty());}
 private void capture()throws Exception{ins.waitForIdleSync();Thread.sleep(250);android.graphics.Bitmap shot=ins.getUiAutomation().takeScreenshot();assertNotNull(shot);try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"dj-duration.png"))){shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{shot.recycle();}}
}
